def f(n, v2):
    n = 0
    i = 0
    k = 0
    j = 0
    l = 0
    v2 = 0
    v3 = 0
    v4 = 0
    while l < n:
        if ( not (l%6)):
            v2 = v2 + 1
        else:
            if( not (l%5))
	    v3 = v3 + 1
        if ( not (l%4)):
            v4 = v4 + 1
        else:
            if( not (l%3))
	    i = i + 1
        if ( not (l%2)):
            j = j+1
        else:
            k = k+1
        l = l+1
    assert (i+j+k+v4+v3+v2) == l
    return
